#include <vector>
#include <cstddef>
#include <cmath>
#include <stdexcept>
#include <omp.h>

struct COOElement {
   size_t row, column;
   double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) {
        throw std::invalid_argument("solveLinearSystem: b.size() must equal N");
    }

    x.assign(N, 0.0);
    if (N == 0) return;

    // Build a dense augmented matrix [A | b].
    // This avoids unsafe concurrent writes by assigning each row to exactly one thread.
    std::vector<double> aug(N * (N + 1), 0.0);

    // COO -> dense accumulation. Multiple COO entries may map to the same (row, col),
    // so use atomic updates.
    #pragma omp parallel for default(none) shared(A, aug, N)
    for (std::ptrdiff_t k = 0; k < static_cast<std::ptrdiff_t>(A.size()); ++k) {
        const COOElement &e = A[static_cast<size_t>(k)];
        if (e.row >= N || e.column >= N) continue;
        #pragma omp atomic update
        aug[e.row * (N + 1) + e.column] += e.value;
    }

    // Fill RHS column.
    #pragma omp parallel for default(none) shared(aug, b, N)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
        aug[static_cast<size_t>(i) * (N + 1) + N] = b[static_cast<size_t>(i)];
    }

    // Gaussian elimination with partial pivoting.
    for (size_t k = 0; k < N; ++k) {
        // Find pivot row (serial, simple and deterministic).
        size_t pivot = k;
        double maxAbs = std::fabs(aug[k * (N + 1) + k]);
        for (size_t i = k + 1; i < N; ++i) {
            const double v = std::fabs(aug[i * (N + 1) + k]);
            if (v > maxAbs) {
                maxAbs = v;
                pivot = i;
            }
        }

        if (maxAbs == 0.0) {
            throw std::runtime_error("solveLinearSystem: singular matrix");
        }

        // Swap rows if needed (serial).
        if (pivot != k) {
            for (size_t j = k; j <= N; ++j) {
                const size_t idx1 = k * (N + 1) + j;
                const size_t idx2 = pivot * (N + 1) + j;
                const double tmp = aug[idx1];
                aug[idx1] = aug[idx2];
                aug[idx2] = tmp;
            }
        }

        const double pivotVal = aug[k * (N + 1) + k];

        // Eliminate rows below pivot in parallel.
        // Each thread updates a distinct row i, so no conflicting writes.
        #pragma omp parallel for default(none) shared(aug, N, k, pivotVal)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k) + 1; ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            const size_t i = static_cast<size_t>(ii);
            const size_t rowBase = i * (N + 1);
            const size_t pivotBase = k * (N + 1);

            const double factor = aug[rowBase + k] / pivotVal;
            aug[rowBase + k] = 0.0;

            for (size_t j = k + 1; j <= N; ++j) {
                aug[rowBase + j] -= factor * aug[pivotBase + j];
            }
        }
    }

    // Back substitution.
    for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(N) - 1; ii >= 0; --ii) {
        const size_t i = static_cast<size_t>(ii);
        double sum = 0.0;

        // Parallel reduction for the dot product of row i with already-known x entries.
        #pragma omp parallel for default(none) shared(aug, x, N, i) reduction(+:sum)
        for (std::ptrdiff_t jj = static_cast<std::ptrdiff_t>(i) + 1; jj < static_cast<std::ptrdiff_t>(N); ++jj) {
            const size_t j = static_cast<size_t>(jj);
            sum += aug[i * (N + 1) + j] * x[j];
        }

        const double diag = aug[i * (N + 1) + i];
        if (diag == 0.0) {
            throw std::runtime_error("solveLinearSystem: singular matrix during back substitution");
        }
        x[i] = (aug[i * (N + 1) + N] - sum) / diag;
    }
}
